-- Briefs precise on WHAT and WHY, checked before they reach the maker, and corrected in place (the lead video editor's
-- feedback, Nov 2026). One log for everything that happens to a brief before and after it goes out:
-- - correction: a message in the revise chat under the brief, the AI's structured patch, before and after (undo marks
--   it undone). Each one also becomes a learning for the brief writer (agent_learnings, source_table brief_corrections).
-- - review: "Mark reviewed": the stamp "Generated by Kaizen Ads · reviewed by <name>" on the brief, the ticket and the
--   PDF, valid for the brief exactly as it was reviewed (brief_hash).
-- - override: a lead sent a blocked brief anyway (needs client input, waiting on assets, contradictions) with a reason.
-- - answer / ask_client: a fact only the client knows, answered in the app or routed to the client as a Brand Bible
--   question.
-- Drafts in Ready to send have no request yet: their rows are found by client and brief_hash, so the stamp and an
-- override carry over to the tickets made from that exact brief.

create table if not exists public.brief_corrections (
  id uuid primary key default gen_random_uuid(),
  client_id uuid not null references public.clients(id) on delete cascade,
  request_id uuid references public.requests(id) on delete set null,
  suggestion_id uuid references public.creative_suggestions(id) on delete set null,
  profile_id uuid references public.profiles(id) on delete set null,
  kind text not null default 'correction' check (kind in ('correction', 'review', 'override', 'answer', 'ask_client')),
  instruction text,
  reply text,
  before jsonb,
  after jsonb,
  changes jsonb not null default '[]',
  brief_hash text,
  gates text[] not null default '{}',
  reason text,
  format text,
  undone_at timestamptz,
  created_at timestamptz not null default now()
);

comment on table public.brief_corrections is 'Everything done to a brief around sending it: revise-chat corrections (before/after, undo), reviews (the stamp), lead overrides of the ready gates, answers to client-only facts';
comment on column public.brief_corrections.brief_hash is 'The brief (text and sizes) the row applies to: a review or override holds only while the brief is exactly this';

create index if not exists brief_corrections_client on public.brief_corrections (client_id, created_at desc);
create index if not exists brief_corrections_request on public.brief_corrections (request_id, created_at desc) where request_id is not null;
create index if not exists brief_corrections_hash on public.brief_corrections (client_id, brief_hash, kind) where brief_hash is not null;

alter table public.brief_corrections enable row level security;
drop policy if exists "staff read brief corrections" on public.brief_corrections;
create policy "staff read brief corrections" on public.brief_corrections for select to authenticated using (private.staff_can_see_client(client_id));
-- Written by the server (service role) after the person's access and role are checked
